import{KOLLERU_DATA}from"./kolleru-data.js";function initTheme(){const t=document.getElementById("theme-toggle");t&&t.addEventListener("click",()=>{document.body.classList.toggle("light-theme");const e=document.body.classList.contains("light-theme");localStorage.setItem("theme",e?"light":"dark"),t.textContent=e?"🌙":"☀️"})}function initNavbar(){const t=document.getElementById("menu-toggle"),e=document.getElementById("nav-menu");t&&e&&t.addEventListener("click",()=>{const n="true"===t.getAttribute("aria-expanded");t.setAttribute("aria-expanded",!n),e.classList.toggle("active")})}function renderStats(){const t=document.getElementById("stats-grid");t&&KOLLERU_DATA.stats&&(t.innerHTML=KOLLERU_DATA.stats.map(t=>`\n        <div class="stat-card">\n            <span class="stat-icon">${t.icon}</span>\n            <div class="stat-value">${t.value}</div>\n            <div class="stat-label">${t.label}</div>\n        </div>\n    `).join(""))}function renderGeography(){const t=document.getElementById("geo-title"),e=document.getElementById("geo-content");t&&(t.textContent=KOLLERU_DATA.geography.title),e&&(e.textContent=KOLLERU_DATA.geography.content)}function renderSanctuaryAndRamsar(){const t=document.getElementById("ramsar-title"),e=document.getElementById("ramsar-content"),n=document.getElementById("sanctuary-title"),o=document.getElementById("sanctuary-content");t&&(t.textContent=KOLLERU_DATA.ramsarSite.title),e&&(e.textContent=KOLLERU_DATA.ramsarSite.content),n&&(n.textContent=KOLLERU_DATA.birdSanctuary.title),o&&(o.textContent=KOLLERU_DATA.birdSanctuary.content)}function renderEcosystemAndFish(){const t=document.getElementById("eco-title"),e=document.getElementById("eco-content"),n=document.getElementById("fish-title"),o=document.getElementById("fish-content");t&&(t.textContent=KOLLERU_DATA.freshwaterEcosystem.title),e&&(e.textContent=KOLLERU_DATA.freshwaterEcosystem.content),n&&(n.textContent=KOLLERU_DATA.fishDiversity.title),o&&(o.textContent=KOLLERU_DATA.fishDiversity.content)}function renderBirds(){const t=document.getElementById("birds-grid");t&&KOLLERU_DATA.migratoryBirds&&(t.innerHTML=KOLLERU_DATA.migratoryBirds.map(t=>`\n        <div class="bird-card">\n            <h4>🦢 ${t.name}</h4>\n            <span class="bird-status">${t.status}</span>\n            <p>${t.desc}</p>\n        </div>\n    `).join(""))}function renderMapHotspots(){const t=document.getElementById("hotspots-list");t&&KOLLERU_DATA.hotspots&&(t.innerHTML=KOLLERU_DATA.hotspots.map((t,e)=>`\n        <button class="spot-btn ${0===e?"active":""}" data-id="${t.id}">\n            <span class="spot-name">${t.name}</span>\n        </button>\n    `).join(""),showHotspotDetail(KOLLERU_DATA.hotspots[0]),t.addEventListener("click",t=>{const e=t.target.closest(".spot-btn");if(!e)return;const n=e.getAttribute("data-id"),o=KOLLERU_DATA.hotspots.find(t=>t.id===n);document.querySelectorAll(".spot-btn").forEach(t=>t.classList.remove("active")),e.classList.add("active"),o&&showHotspotDetail(o)}))}function showHotspotDetail(t){const e=document.getElementById("hotspot-detail");e&&(e.innerHTML=`\n        <h3 style="margin: 0 0 0.5rem; color: #38bdf8; font-size: 1.5rem;">${t.name}</h3>\n        <p style="color: var(--kolleru-text-sub); line-height: 1.6; margin-bottom: 1.25rem;">${t.desc}</p>\n        <div style="font-family: monospace; font-size: 0.85rem; color: #94a3b8; background: rgba(0,0,0,0.2); padding: 0.5rem 0.85rem; border-radius: 0.5rem;">Coordinates: ${t.lat}° N, ${t.lng}° E</div>\n    `)}function renderGallery(){const t=document.getElementById("gallery-grid");t&&KOLLERU_DATA.gallery&&(t.innerHTML=KOLLERU_DATA.gallery.map(t=>`\n        <div class="gallery-card">\n            <img src="${t.url}" alt="${t.title}" loading="lazy" />\n            <div class="gallery-info">\n                <h4>${t.title}</h4>\n                <p>${t.caption}</p>\n            </div>\n        </div>\n    `).join(""))}function renderFacts(){const t=document.getElementById("facts-grid");t&&KOLLERU_DATA.facts&&(t.innerHTML=KOLLERU_DATA.facts.map(t=>`<div class="trivia-box">💡 ${t}</div>`).join(""))}document.addEventListener("DOMContentLoaded",()=>{initTheme(),initNavbar(),renderStats(),renderGeography(),renderSanctuaryAndRamsar(),renderEcosystemAndFish(),renderBirds(),renderMapHotspots(),renderGallery(),renderFacts()});